files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

.page {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
}

.page::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  background-color: rgba(0 0 0 / 0.5);
}

.quote {
  max-width: 650px;
  padding: 50px;
  color: #000;
  background-color: #fff;
}

.quote__text {
  font-size: 32px;
  font-style: italic;
  line-height: 1.37;
}

.quote__author {
  margin-block-start: 25px;
  margin-block-end: 0;
  font-size: 18px;
  font-style: italic;
  line-height: 1.4;
  text-align: right;
}

.page__video {
  position: absolute;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

@media not screen, (max-width: 768px) {
  .page__video,
  .page::before {
    display: none;
  }
}
